 async function restaurarPendentes(cont){if(!['Amanda','Chris','Cecília'].includes(contexto().papel))return;const ids=[...new Set(fluxo.listar().filter(pendente).map(s=>s.id))];for(const id of ids){const fisico=alvo(id);if(fisico?.isConnected&&fisico!==cont)recuperacoes(fisico,id);else if(cont?.isConnected)recuperacoes(cont,cont.__fichaPostIdI165||null);}}
