 async function anexarStokki(painel,posts){const c=copia(contexto()),ticket={};painel.__stokkiI165=ticket;try{const habilitada=await ativa();if(contextoChave(c)!==contextoChave(contexto())||!painel.isConnected||painel.__stokkiI165!==ticket)return;if(!habilitada&&!fluxo.listar().some(s=>s.tipo==='stokki'&&pendente(s)))return;for(const p of posts){const card=[...painel.querySelectorAll('[data-stokki-post]')].find(e=>e.dataset.stokkiPost===p.id);if(!card)continue;card.__fichaPostI165={};card.__fichaPostIdI165=p.id;const guard=capturarCont(card);let apoio=document.createElement('section');apoio.className='i165-post-action';apoio.innerHTML='<h4>Organização desta publicação</h4>'+(c.papel==='Amanda'?'<button type="button" data-stokki165="adotar">Definir data, semana e prioridade</button>':'')+(p.publicacaoStokki?.selecionadas||[]).map(rede=>'<div><b>'+escI165(rede)+'</b><button type="button" data-stokki165="pedir" data-rede="'+escI165(rede)+'">Pedir mudança à Amanda</button>'+(c.papel==='Amanda'&&p.provasPublicacaoI165?.[rede]&&!p.provasPublicacaoI165[rede].invalidada?'<button type="button" data-stokki165="divergencia" data-rede="'+escI165(rede)+'">Conferir diferença de datas</button>':'')+'</div>').join('');apoio.onclick=e=>{if(!apoio.isConnected||!contVigente(guard))return;const b=e.target.closest?.('[data-stokki165]');if(!b)return;const rede=b.dataset.rede;if(b.dataset.stokki165==='adotar')return abrirFluxo('adotar_diretriz',p.id,card);if(b.dataset.stokki165==='divergencia')return tratarFato(p.id,{tipo:'conferir_divergencia',rede},card);if(b.dataset.stokki165==='pedir'){const bloco=[...card.querySelectorAll('[data-stokki-rede]')].find(x=>x.dataset.stokkiRede===rede);return pedirNaRede(p.id,card,{tipo:'agendar',rede,data:bloco?.querySelector('[data-stokki-data]')?.value||'',hora:bloco?.querySelector('[data-stokki-hora]')?.value||''});}};card.appendChild(apoio);void anexarHistoricoPedidos(card,p.id);for(const s of fluxo.listar())if(s.id===p.id&&['stokki','solicitar_excecao','adotar_diretriz','publicacao'].includes(s.tipo))montar(s.tipo,s.id,card);}}catch(e){if(contextoChave(c)===contextoChave(contexto())&&painel.isConnected)toast('Não consegui conferir os controles da Stokki agora. '+e.message,'erro');}}

async function tratarFato(id,entrada={},contArg=null){const c=copia(contexto()),a=contArg?capturarCont(contArg):null;try{const habilitada=await ativa();if(contextoChave(c)!==contextoChave(contexto())||a&&!contVigente(a))return{tratada:true,resultado:{ok:false,contextoMudou:true}};if(!habilitada&&!fluxo.pendente('publicacao',id))return{tratada:false};const cont=contArg||alvo(id,entrada.origem);if(!cont?.isConnected)throw Error('Abra a postagem novamente.');if(conflitoAnterior('publicacao',id,{tipo:entrada.tipo||'publicar'},cont))return{tratada:true,resultado:{ok:false,recuperacaoPendente:true}};montar('publicacao',id,cont);await fluxo.abrir('publicacao',id,{tipo:entrada.tipo||'publicar',rede:entrada.rede||'geral',motivo:entrada.motivo||''});revelar('publicacao',id);const estado=fluxo.estado('publicacao',id);if(estado.snapshot?.postagem?.cliente==='stokki'&&entrada.tipo!=='conferir_divergencia'&&contextoChave(c)===contextoChave(contexto())){const m=montagens.get(mk('publicacao',id));if(m?.el.isConnected)m.el.remove();await abrirPostagem(id);}return{tratada:true,resultado:{ok:false,conferenciaAbertaI165:true}};}catch(e){if(contextoChave(c)===contextoChave(contexto()))toast(e.message,'erro');return{tratada:true,resultado:{ok:false}};}}
 async function tratarStokki(id,acaoStokki,assinaturaExibida,cont){const c=copia(contexto()),a=capturarCont(cont);try{const habilitada=await ativa();if(contextoChave(c)!==contextoChave(contexto())||!contVigente(a))return{tratada:true,resultado:{ok:false,contextoMudou:true,conferenciaAbertaI165:true}};if(!habilitada&&!fluxo.pendente('stokki',id))return{tratada:false};montar('stokki',id,cont);await fluxo.abrir('stokki',id,{acaoStokki,assinaturaExibida});return{tratada:true,resultado:{ok:false,conferenciaAbertaI165:true}};}catch(e){if(contVigente(a))toast(e.message,'erro');return{tratada:true,resultado:{ok:false,conferenciaAbertaI165:true}};}}
